obj Stack[T] {
    has items: list[T] = [];
    def append(item: T) {
        items.append(item);
    }
    def pop() -> T | None {
        if len(items) > 0 {
            return items.pop();
        }
        return None;
    }
}

with entry {
    s = Stack();
    s.append("Alice");
    s.append("Bob");
    s.append("Charlie");
    popped = s.pop();
    print("Popped:", popped);
    print("Remaining:", s.items);
}

obj Counter {
    has count: int = 0;

    def inc() -> int {
        self.count += 1;
        return self.count;
    }

    def dec() -> int {
        self.count -= 1;
        return self.count;
    }
}

