with entry {
    # (1 + 2) * 3 ** 2
    # Exponentiation (**=18) first, then addition (+ = 15), then multiplication (* = 16)
    expr1 = (1 + 2) * 3 ** 2;
    print("(1 + 2) * 3 ** 2 =", expr1, "(3 * 9 = 27)");

    # not False and True or False
    # not (=8), and (=7), or (=6); not binds tightest
    expr2 = not False and True or False;
    print("not False and True or False =", expr2, "((True and True) or False = True)");

    # 4 << 1 + 1
    # + (=15) before << (=13)
    expr3 = 4 << 1 + 1;
    print("4 << 1 + 1 =", expr3, "(4 << 2 = 16)");

    # 5 < 10 == True
    # <, == (both =9), chain left to right
    expr4 = 5 < 10 == True;
    print("5 < 10 == True =", expr4, "((5 < 10) and (10 == True) = False)");
}

